package android.graphics;
public class Typeface {final java.awt.Font font;private Typeface(java.awt.Font f){font=f;}public static final Typeface DEFAULT_BOLD=new Typeface(new java.awt.Font(java.awt.Font.SANS_SERIF,java.awt.Font.BOLD,16));public static final Typeface MONOSPACE=new Typeface(new java.awt.Font(java.util.Arrays.asList(java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames()).contains("Consolas")?"Consolas":java.awt.Font.MONOSPACED,0,16));public static Typeface createFromFile(java.io.File f){try{return new Typeface(java.awt.Font.createFont(java.awt.Font.TRUETYPE_FONT,f));}catch(Exception e){throw new IllegalArgumentException("Invalid font",e);}}}
